-- Source: CNS North Korea Missile Test Database (Nuclear Threat Initiative / James Martin Center for Nonproliferation Studies) (303 rows)
-- Generated by gen_mart_models.py

with source as (
    select * from {{ source('ripple_raw', 'INTL_NTI_CNS_DPRK_MISSILE_TESTS') }}
)

select
    F1 as f1,
    {{ ripple_dt('"DATE"') }} as date,
    try_to_date(DATE_ENTERED_UPDATED) as date_entered_updated,
    LAUNCH_TIME_UTC as launch_time_utc,
    MISSILE_NAME as missile_name,
    MISSILE_TYPE as missile_type,
    LAUNCH_AGENCY_AUTHORITY as launch_agency_authority,
    FACILITY_NAME as facility_name,
    FACILITY_LOCATION as facility_location,
    OTHER_NAME as other_name,
    try_to_double(FACILITY_LATITUDE) as facility_latitude,
    try_to_double(FACILITY_LONGITUDE) as facility_longitude,
    LANDING_LOCATION as landing_location,
    APOGEE as apogee,
    DISTANCE_TRAVELLED as distance_travelled,
    CONFIRMATION_STATUS as confirmation_status,
    TEST_OUTCOME as test_outcome,
    ADDITIONAL_INFORMATION as additional_information,
    SOURCE_S as source_s
from source
